/**
 * @method
 * @name sessionCheck
 * @description
 * @param
 * @hidden N
 * @exception
 * @example
 */ 
scwin.sessionCheck = function(){
    if(!$p){
        $p = $w;
    }
	if((scwin.js_id == null) || (scwin.js_id.length<0)){
        scwin.goLogin();        
	}	 
}

/**
 * @method
 * @name getExcelDownPath
 * @description
 * @param
 * @hidden N
 * @exception
 * @example
 */ 
scwin.getExcelDownPath = function() {
	return (scwin.js_access_tp == '1' ) ? 'k:\\개인 폴더\\':'c:\\staffDownload\\';
}

/**
 * @method
 * @name info
 * @description
 * @param
 * @hidden N
 * @exception
 * @example
 */ 
scwin.info = function(param) {
    if(!param){
        param = $p;
    }
    console.log(scwin[param]);
    return scwin[param];
};


/**
 * @method
 * @name setUserInfo
 * @description 사용자 정보를 셋팅합니다.
 * @param
 * @hidden N
 * @exception 
 * @example 
 * 
 *  $c.session.setUserInfo();
 */ 
scwin.setUserInfo = function(){

    var xhr = new XMLHttpRequest();
		xhr.open("GET",
		    scwin.url,
		    false
		);
		xhr.send();
		if(xhr.status != 200 ){
			let rslt = JSON.parse(xhr.responseText);
			if(!rslt.success){
				if(rslt.message.indexOf("인증이") > -1){
					console.log("로그인으로 갑니다.");
					//$c.session.goLogin();
				}else{
					console.log("다른 에러",rslt);
				}
                return false;
			}
		}else{
            let rslt = JSON.parse(xhr.responseText);
            if(rslt && rslt.success && rslt.body){            
                let _jsn = rslt.body;
                /*{
                    "id": "112031",
                    "empNo": "112031",
                    "empNm": "홍길동",
                    "email": "user@krx.co.kr",
                    "usrTpCd": "4",
                    "depCd": "2610",
                    "duty": "N",
                    "dutyChrg": "N",
                    "jobtitl": "03",
                    "market": "1",
                    "gduty": "11",
                    "sndloc": "11",
                    "depNm": "공시제도팀",
                    "belngDepCd": "2600",
                    "svrGubun": "dev",
                    "bondYn": "N",
                    "dutyTpCd": "",
                    "insideEmail": "user@krx.co.kr",
                    "accessTp": "1"
                }
                */
                scwin.js_id			  = _jsn.id;
                scwin.js_emp_no		  = _jsn.empNo;
                scwin.js_pass		  = "";
                scwin.js_emp_nm		  = _jsn.empNm;              
                scwin.js_email		  = _jsn.email;
                scwin.js_usr_tp_cd	  = _jsn.usrTpCd;
                scwin.js_dep_cd		  = _jsn.depCd;
                scwin.js_duty		  = _jsn.duty;
                scwin.js_duty_chrg	  = _jsn.dutyChrg;
                scwin.js_jobtitl	  = _jsn.jobtitl;
                scwin.js_market		  = _jsn.market;
                scwin.js_gduty		  = _jsn.gduty;
                scwin.js_sndloc		  = _jsn.sndloc;
                scwin.js_dep_nm 	  = _jsn.depNm;
                scwin.js_team 		  = "";
                scwin.js_belngdepcd	  = _jsn.belngDepCd;	
                scwin.js_svrGubun	  = _jsn.svrGubun;
                scwin.js_bond_yn      = _jsn.bondYn;		//채권상장팀이면 Y가 셋팅..	
                scwin.js_duty_tp_cd	  = _jsn.dutyTpCd;
                scwin.js_inside_email = _jsn.insideEmail;
                scwin.js_access_tp	  = _jsn.accessTp;

                //tobe 포함
                scwin.id = _jsn.id;
                scwin.empNo = _jsn.empNo;
                scwin.pass = "";
                scwin.empNm = _jsn.empNm;              
                scwin.email = _jsn.email;
                scwin.usrTpCd = _jsn.usrTpCd;
                scwin.depCd = _jsn.depCd;
                scwin.duty = _jsn.duty;
                scwin.dutyChrg = _jsn.dutyChrg;
                scwin.jobtitl = _jsn.jobtitl;
                scwin.market = _jsn.market;
                scwin.gduty = _jsn.gduty;
                scwin.sndloc = _jsn.sndloc;
                scwin.depNm = _jsn.depNm;
                scwin.team   = "";
                scwin.belngDepCd = _jsn.belngDepCd;	
                scwin.svrGubun = _jsn.svrGubun;
                scwin.bondYn = _jsn.bondYn;		//채권상장팀이면 Y가 셋팅..	
                scwin.dutyTpCd = _jsn.dutyTpCd;
                scwin.insideEmail = _jsn.insideEmail;
                scwin.accessTp = _jsn.accessTp;

                return true;        

            }else{
                return false;   
            }
        }

    //return userInfo.responseJSON.body;
};

